    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Interior colors on the repeating 7x7 tile lattice; the most frequent
    # interior color is the background motif, while rarer colors are linked.
    from collections import Counter
    freq=Counter(grid[r][c] for r in range(2,h,7) for c in range(2,w,7)
                 if grid[r][c] != 0)
    if not freq: return out
    base=freq.most_common(1)[0][0]
    special=set(freq)-{base}
